import 'package:file_picker/file_picker.dart';import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../core/app_state.dart';
class SettingsScreen extends StatefulWidget{const SettingsScreen({super.key});@override State<SettingsScreen>createState()=>_SettingsScreenState();}class _SettingsScreenState extends State<SettingsScreen>{late TextEditingController python,engine,checkpoint,output,api;@override void didChangeDependencies(){super.didChangeDependencies();final x=context.read<AppState>().config;python=TextEditingController(text:x.python);engine=TextEditingController(text:x.engineDirectory);checkpoint=TextEditingController(text:x.checkpoint);output=TextEditingController(text:x.outputDirectory);api=TextEditingController(text:x.apiUrl);}@override Widget build(BuildContext c){final s=c.watch<AppState>();return Scaffold(appBar:AppBar(title:const Text('Settings')),body:SingleChildScrollView(padding:const EdgeInsets.all(28),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:760),child:Column(children:[field(python,'Python executable'),field(engine,'XAI-Compress engine directory',pick:()async{final p=await FilePicker.platform.getDirectoryPath();if(p!=null)engine.text=p;}),field(checkpoint,'Neural checkpoint .pt',pick:()async{final r=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['pt']);if(r!=null)checkpoint.text=r.files.single.path??'';}),field(output,'Default output directory',pick:()async{final p=await FilePicker.platform.getDirectoryPath();if(p!=null)output.text=p;}),field(api,'FastAPI base URL'),SwitchListTile(value:s.darkMode,onChanged:s.toggleDark,title:const Text('Dark mode')),const SizedBox(height:12),FilledButton(onPressed:()async{final x=s.config;x.python=python.text;x.engineDirectory=engine.text;x.checkpoint=checkpoint.text;x.outputDirectory=output.text;x.apiUrl=api.text;await s.saveSettings();if(mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Settings saved')));},child:const Text('Save settings'))]))));}Widget field(TextEditingController c,String label,{VoidCallback?pick})=>Padding(padding:const EdgeInsets.only(bottom:14),child:TextField(controller:c,decoration:InputDecoration(labelText:label,suffixIcon:pick==null?null:IconButton(onPressed:pick,icon:const Icon(Icons.folder_open)))));}
